from functools import lru_cache
from math import gcd


@lru_cache(maxsize=None)
def _suffix_count(length: int, digit_sum: int, needed: int) -> int:
    """Count nonzero-digit suffixes with this sum and product requirement."""
    if digit_sum < length or digit_sum > 9 * length:
        return 0
    if length == 0:
        return int(digit_sum == 0 and needed == 1)
    return sum(
        _suffix_count(length - 1, digit_sum - digit, needed // gcd(needed, digit))
        for digit in range(1, 10)
    )


def _count_up_to(bound: int) -> int:
    if bound <= 0:
        return 0
    digits = [int(c) for c in str(bound)]
    length = len(digits)

    # Every positive number containing a zero has digit product zero.
    nonzero_count = sum(9 ** size for size in range(1, length))
    for index, digit in enumerate(digits):
        if digit == 0:
            break
        nonzero_count += (digit - 1) * 9 ** (length - index - 1)
    else:
        nonzero_count += 1
    answer = bound - nonzero_count

    # A product of nonzero decimal digits has no prime factors above seven.
    for target_sum in range(1, 9 * length + 1):
        rest = target_sum
        for prime in (2, 3, 5, 7):
            while rest % prime == 0:
                rest //= prime
        if rest != 1:
            continue

        for size in range(1, length):
            answer += _suffix_count(size, target_sum, target_sum)

        remaining_sum = target_sum
        needed = target_sum
        for index, digit in enumerate(digits):
            for smaller in range(1, digit):
                answer += _suffix_count(
                    length - index - 1,
                    remaining_sum - smaller,
                    needed // gcd(needed, smaller),
                )
            if digit == 0:
                break
            remaining_sum -= digit
            needed //= gcd(needed, digit)
        else:
            answer += int(remaining_sum == 0 and needed == 1)
    return answer


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count beautiful positive integers in the inclusive range [l, r].

    A number is beautiful if its digit product is divisible by its digit sum.
    The bounds satisfy 1 <= l <= r < 10**9.
    """
    return _count_up_to(r) - _count_up_to(l - 1)

def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper three-colour completions, modulo 998244353.

    Every edge-sharing pair must have different digits. The frontier stores
    the most recently visited cell in each column; transposition keeps its
    width at most sqrt(H * W).
    """
    mod = 998244353
    if W > H:
        grid = ["".join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    # Reject incompatible fixed cells before building the frontier.
    for r in range(H):
        for c in range(W):
            digit = grid[r][c]
            if digit == "?":
                continue
            if r and grid[r - 1][c] == digit:
                return 0
            if c and grid[r][c - 1] == digit:
                return 0

    # Two bits per cell, with zero reserved for unvisited cells.
    shift = 2 * (W - 1)
    mask = (1 << (2 * W)) - 1
    choices = {
        (above, left): tuple(
            digit for digit in (1, 2, 3)
            if digit != above and digit != left
        )
        for above in range(4)
        for left in range(4)
    }
    dp = {0: 1}
    for r in range(H):
        for c in range(W):
            fixed = grid[r][c]
            next_dp = {}
            if fixed == "?":
                for state, count in dp.items():
                    above = state >> shift
                    left = (state & 3) if c else 0
                    base = (state << 2) & mask
                    for digit in choices[above, left]:
                        target = base | digit
                        next_dp[target] = (next_dp.get(target, 0) + count) % mod
            else:
                digit = int(fixed)
                for state, count in dp.items():
                    if state >> shift == digit:
                        continue
                    if c and state & 3 == digit:
                        continue
                    target = ((state << 2) & mask) | digit
                    next_dp[target] = (next_dp.get(target, 0) + count) % mod
            dp = next_dp
            if not dp:
                return 0
    return sum(dp.values()) % mod

