from functools import lru_cache


def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """Count integers in [low, high] divisible by k with equal even/odd digit counts.

    Bounds satisfy 0 < low <= high <= 10**9 and 0 < k <= 20.
    Leading zeroes are not digits of a number.

    >>> count_beautiful_integers(10, 20, 3)
    2
    >>> count_beautiful_integers(1, 10, 1)
    1
    >>> count_beautiful_integers(5, 5, 2)
    0
    """
    def count_up_to(bound: int) -> int:
        if bound <= 0:
            return 0
        digits = tuple(map(int, str(bound)))
        length = len(digits)

        @lru_cache(maxsize=None)
        def dp(pos: int, balance: int, remainder: int,
               started: bool, tight: bool) -> int:
            remaining = length - pos
            if abs(balance) > remaining:
                return 0
            if pos == length:
                return int(started and balance == 0 and remainder == 0)

            limit = digits[pos] if tight else 9
            total = 0
            for digit in range(limit + 1):
                next_tight = tight and digit == digits[pos]
                if not started and digit == 0:
                    total += dp(pos + 1, 0, 0, False, next_tight)
                else:
                    total += dp(
                        pos + 1,
                        balance + (1 if digit % 2 == 0 else -1),
                        (remainder * 10 + digit) % k,
                        True,
                        next_tight,
                    )
            return total

        return dp(0, 0, 0, False, True)

    return count_up_to(high) - count_up_to(low - 1)

def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """Count replacements having at least k deletable contiguous substrings.

    Pairs of equal letters and triples ABC may be deleted. A substring is
    deletable exactly when the three letter counts have the same parity.
    Return the number of replacements modulo 998244353 (n <= 50).
    """
    mod = 998244353
    if k == 0:
        return pow(3, s.count('?'), mod)
    # Consecutive prefix XOR values differ, so each value occurs at most
    # ceil((n + 1) / 2) times. Concentrating visits on two values maximizes
    # the number of equal-prefix pairs.
    if k > n * n // 4:
        return 0

    # Counts are indexed relative to the current prefix XOR. This removes
    # the need to store the endpoint separately. Initially only the empty
    # prefix has been visited.
    dp = {(1, 0, 0, 0): 1}
    codes = {'A': 1, 'B': 2, 'C': 3}
    for ch in s:
        choices = (1, 2, 3) if ch == '?' else (codes[ch],)
        following = {}
        for counts, ways in dp.items():
            for step in choices:
                state = (counts[step] + 1, counts[1 ^ step],
                         counts[2 ^ step], counts[3 ^ step])
                total = following.get(state, 0) + ways
                if total >= mod:
                    total -= mod
                following[state] = total
        dp = following

    # Every pair of equal prefix XORs identifies one nonempty good substring.
    return sum(ways for counts, ways in dp.items()
               if sum(c * (c - 1) // 2 for c in counts) >= k) % mod

