from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether some of the rotatable tiles exactly cover an h by w grid.

    Tiles align with grid cells, may not overlap or extend outside the grid,
    and each available tile may be used at most once.
    """
    shapes = [tuple(sorted(tile)) for tile in tiles[:n]
              if (tile[0] <= h and tile[1] <= w)
              or (tile[1] <= h and tile[0] <= w)]
    count = len(shapes)
    full = (1 << (h * w)) - 1
    areas = [a * b for a, b in shapes]

    # Bit k of possible[mask] says that a subset of mask has total area k.
    possible = [1] * (1 << count)
    for mask in range(1, 1 << count):
        bit = mask & -mask
        i = bit.bit_length() - 1
        rest = possible[mask ^ bit]
        possible[mask] = rest | (rest << areas[i])

    placements = []
    for a, b in shapes:
        by_cell = []
        for cell in range(h * w):
            row, col = divmod(cell, w)
            options = []
            for height, width in {(a, b), (b, a)}:
                if row + height <= h and col + width <= w:
                    rectangle = 0
                    strip = (1 << width) - 1
                    for offset in range(height):
                        rectangle |= strip << (cell + offset * w)
                    options.append(rectangle)
            by_cell.append(options)
        placements.append(by_cell)

    @lru_cache(None)
    def search(occupied: int, remaining: int) -> bool:
        if occupied == full:
            return True
        needed = h * w - occupied.bit_count()
        if not (possible[remaining] >> needed) & 1:
            return False
        empty = full ^ occupied
        cell = (empty & -empty).bit_length() - 1
        seen = set()
        for i, shape in enumerate(shapes):
            bit = 1 << i
            if not remaining & bit or shape in seen:
                continue
            seen.add(shape)
            # The first uncovered cell must be the top-left cell of its tile:
            # every cell earlier in row order is already occupied.
            for rectangle in placements[i][cell]:
                if not rectangle & occupied:
                    if search(occupied | rectangle, remaining ^ bit):
                        return True
        return False

    return search(0, (1 << count) - 1)

from typing import List, Tuple


def max_alkane_vertices(n: int, edges: List[Tuple[int, int]]) -> int:
    """Return the largest subtree whose degrees are 1 or 4, with a degree-4 vertex.

    Return -1 when no such subtree exists. Vertices are numbered 1 through n.
    Runs in O(n) time and space, without recursion.
    """
    adjacency = [[] for _ in range(n + 1)]
    for a, b in edges:
        adjacency[a].append(b)
        adjacency[b].append(a)

    parent = [0] * (n + 1)
    order = [1]
    for vertex in order:
        for neighbor in adjacency[vertex]:
            if neighbor != parent[vertex]:
                parent[neighbor] = vertex
                order.append(neighbor)

    # branch[v] includes v and assumes its edge to its parent is selected.
    # Thus v is either a leaf, or uses exactly three child branches.
    branch = [1] * (n + 1)
    answer = -1
    for vertex in reversed(order):
        largest = []
        for child in adjacency[vertex]:
            if parent[child] == vertex:
                largest.append(branch[child])
                largest.sort(reverse=True)
                if len(largest) > 4:
                    largest.pop()

        if len(largest) >= 3:
            branch[vertex] = 1 + sum(largest[:3])
            if parent[vertex]:
                # The parent may be the topmost leaf of the chosen subtree.
                answer = max(answer, branch[vertex] + 1)
        if len(largest) == 4:
            # Here vertex is the topmost vertex and has four children.
            answer = max(answer, 1 + sum(largest))
    return answer

